The fix removes the wildcard `Principal = "*"` and scopes access to the AWS account (or a specific principal), while keeping the bucket private via `aws_s3_bucket_public_access_block`. Since the intent is bucket logging/data access rather than public read, I've restricted the policy statement's principal to the bucket owner's account (using `data.aws_caller_identity.current`) and added a public access block for defense in depth.

```hcl
data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "data" {
  bucket = "terraveritas-negcase2-bucket"
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket = aws_s3_bucket.data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "data" {
  bucket = aws_s3_bucket.data.id
  rule {
    id     = "expire-old"
    status = "Enabled"
    expiration {
      days = 365
    }
  }
}

resource "aws_s3_bucket_logging" "data" {
  bucket        = aws_s3_bucket.data.id
  target_bucket = "terraveritas-negcase2-logs"
  target_prefix = "log/"
}

resource "aws_s3_bucket_policy" "data" {
  bucket = aws_s3_bucket.data.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "s3:GetObject"
        Resource = "arn:aws:s3:::terraveritas-negcase2-bucket/*"
      }
    ]
